package api.parking_p; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.List; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ParkingControllerTest { @Mock ParkingService service; @InjectMocks ParkingController controller; @Test @DisplayName("UT-BE-PARKING-CTRL-001 주차장 목록을 조회한다") void list(){ List<ParkingDTO>x=List.of(); when(service.list()).thenReturn(x); assertThat(controller.list()).isSameAs(x); } @Test @DisplayName("UT-BE-PARKING-CTRL-002 주차장을 등록한다") void insert(){ ParkingDTO d=new ParkingDTO(); when(service.insert(d)).thenReturn(1); assertThat(controller.insert(d)).isEqualTo(1); } @Test @DisplayName("UT-BE-PARKING-CTRL-003 주차장을 삭제한다") void delete(){ when(service.delete(1)).thenReturn(1); assertThat(controller.delete(1)).isEqualTo(1); } @Test @DisplayName("UT-BE-PARKING-CTRL-004 경로 번호를 설정해 주차장을 수정한다") void update(){ ParkingDTO d=new ParkingDTO(); when(service.update(d)).thenReturn(1); assertThat(controller.update(7,d)).isEqualTo(1); assertThat(d.getParkingNo()).isEqualTo(7); } }
